          if (second.fail && !tiers.llm) tiers.llm = { available: false, findings: [] };
          else if (second.data) stampLintFindings(second.data.findings);
        }
        if (!tiers.llm) {
          tiers.llm = { available: true, method: "api", findings: llmFindings };
        }
      }
    }
